        postTokenUsageStep: postTokenUsageStep,
        truncateErrorText: truncateErrorText,
        buildFailureCommentText: buildFailureCommentText,
        postFailureComment: postFailureComment,
        finalizeFailure: finalizeFailure
    };
}

